// Enhanced Security Service for Government-Grade Voting System
import CryptoJS from 'crypto-js';

export interface SecurityConfig {
  rateLimitWindow: number; // milliseconds
  maxVotesPerWindow: number;
  sessionTimeout: number; // milliseconds
  encryptionKey: string;
  enableBiometric: boolean;
  enable2FA: boolean;
}

export interface SecurityEvent {
  id: string;
  type: 'login' | 'vote_cast' | 'registration' | 'suspicious_activity' | 'voting_error' | 'failed_login' | 'blocked_request' | 'rate_limited';
  timestamp: number;
  ipAddress: string;
  userAgent: string;
  details: any;
  severity: 'low' | 'medium' | 'high' | 'critical';
}

export interface RateLimitInfo {
  count: number;
  windowStart: number;
  isBlocked: boolean;
  remainingAttempts: number;
}

class SecurityService {
  private config: SecurityConfig;
  private rateLimitMap: Map<string, RateLimitInfo> = new Map();
  private securityEvents: SecurityEvent[] = [];
  private activeSessions: Map<string, number> = new Map();
  private suspiciousIPs: Set<string> = new Set();

  constructor() {
    this.config = {
      rateLimitWindow: 5 * 60 * 1000, // 5 minutes
      maxVotesPerWindow: 1, // 1 vote per window
      sessionTimeout: 30 * 60 * 1000, // 30 minutes
      encryptionKey: this.generateEncryptionKey(),
      enableBiometric: false,
      enable2FA: false
    };
  }

  // Rate Limiting
  checkRateLimit(identifier: string): { allowed: boolean; info: RateLimitInfo } {
    const now = Date.now();
    const existing = this.rateLimitMap.get(identifier);

    if (!existing) {
      const newLimit: RateLimitInfo = {
        count: 1,
        windowStart: now,
        isBlocked: false,
        remainingAttempts: this.config.maxVotesPerWindow - 1
      };
      this.rateLimitMap.set(identifier, newLimit);
      return { allowed: true, info: newLimit };
    }

    // Check if window has expired
    if (now - existing.windowStart > this.config.rateLimitWindow) {
      const resetLimit: RateLimitInfo = {
        count: 1,
        windowStart: now,
        isBlocked: false,
        remainingAttempts: this.config.maxVotesPerWindow - 1
      };
      this.rateLimitMap.set(identifier, resetLimit);
      return { allowed: true, info: resetLimit };
    }

    // Check if limit exceeded
    if (existing.count >= this.config.maxVotesPerWindow) {
      existing.isBlocked = true;
      existing.remainingAttempts = 0;
      this.logSecurityEvent('suspicious_activity', {
        identifier,
        reason: 'Rate limit exceeded',
        attempts: existing.count
      }, 'high');
      return { allowed: false, info: existing };
    }

    // Increment count
    existing.count++;
    existing.remainingAttempts = this.config.maxVotesPerWindow - existing.count;
    this.rateLimitMap.set(identifier, existing);
    return { allowed: true, info: existing };
  }

  // Session Management
  createSession(userId: string): string {
    const sessionId = this.generateSessionId();
    const expiry = Date.now() + this.config.sessionTimeout;
    this.activeSessions.set(sessionId, expiry);
    
    this.logSecurityEvent('login', {
      userId,
      sessionId,
      expiry
    }, 'low');
    
    return sessionId;
  }

  validateSession(sessionId: string): boolean {
    const expiry = this.activeSessions.get(sessionId);
    if (!expiry) return false;
    
    if (Date.now() > expiry) {
      this.activeSessions.delete(sessionId);
      return false;
    }
    
    return true;
  }

  invalidateSession(sessionId: string): void {
    this.activeSessions.delete(sessionId);
  }

  // Input Validation and Sanitization
  validateCitizenId(citizenId: string): { valid: boolean; error?: string } {
    // Remove whitespace and convert to uppercase
    const cleaned = citizenId.trim().toUpperCase();
    
    // Check length
    if (cleaned.length < 6 || cleaned.length > 20) {
      return { valid: false, error: "Citizen ID must be 6-20 characters" };
    }
    
    // Check format (alphanumeric only)
    if (!/^[A-Z0-9]+$/.test(cleaned)) {
      return { valid: false, error: "Citizen ID must contain only letters and numbers" };
    }
    
    // Check for suspicious patterns
    if (this.isSuspiciousPattern(cleaned)) {
      this.logSecurityEvent('suspicious_activity', {
        type: 'suspicious_citizen_id',
        value: cleaned
      }, 'medium');
      return { valid: false, error: "Invalid Citizen ID format" };
    }
    
    return { valid: true };
  }

  validateCandidateId(candidateId: string): { valid: boolean; error?: string } {
    const validCandidates = ['1', '2', '3', '4'];
    if (!validCandidates.includes(candidateId)) {
      return { valid: false, error: "Invalid candidate selected" };
    }
    return { valid: true };
  }

  // Encryption and Hashing
  encryptSensitiveData(data: string): string {
    return CryptoJS.AES.encrypt(data, this.config.encryptionKey).toString();
  }

  decryptSensitiveData(encryptedData: string): string {
    const bytes = CryptoJS.AES.decrypt(encryptedData, this.config.encryptionKey);
    return bytes.toString(CryptoJS.enc.Utf8);
  }

  hashData(data: string): string {
    return CryptoJS.SHA256(data).toString();
  }

  // Security Event Logging
  logSecurityEvent(type: SecurityEvent['type'], details: any, severity: SecurityEvent['severity']): void {
    const event: SecurityEvent = {
      id: this.generateEventId(),
      type,
      timestamp: Date.now(),
      ipAddress: this.getClientIP(),
      userAgent: navigator.userAgent,
      details,
      severity
    };
    
    this.securityEvents.push(event);
    
    // Keep only last 1000 events
    if (this.securityEvents.length > 1000) {
      this.securityEvents = this.securityEvents.slice(-1000);
    }
    
    // Check for suspicious patterns
    this.analyzeSecurityPatterns(event);
  }

  // Threat Detection
  private analyzeSecurityPatterns(event: SecurityEvent): void {
    // Check for rapid-fire events from same IP
    const recentEvents = this.securityEvents.filter(e => 
      e.ipAddress === event.ipAddress && 
      (event.timestamp - e.timestamp) < 60000 // 1 minute
    );
    
    if (recentEvents.length > 10) {
      this.suspiciousIPs.add(event.ipAddress);
      this.logSecurityEvent('suspicious_activity', {
        type: 'rapid_fire_events',
        ipAddress: event.ipAddress,
        count: recentEvents.length
      }, 'critical');
    }
  }

  // IP Address Management
  isSuspiciousIP(ipAddress: string): boolean {
    return this.suspiciousIPs.has(ipAddress);
  }

  getClientIP(): string {
    // In a real implementation, this would get the actual client IP
    // For demo purposes, we'll generate a mock IP
    return `192.168.1.${Math.floor(Math.random() * 255)}`;
  }

  // Security Reports
  getSecurityReport(): {
    totalEvents: number;
    criticalEvents: number;
    suspiciousIPs: number;
    activeSessions: number;
    rateLimitedUsers: number;
    recentEvents: SecurityEvent[];
  } {
    const now = Date.now();
    const last24Hours = now - (24 * 60 * 60 * 1000);
    
    return {
      totalEvents: this.securityEvents.length,
      criticalEvents: this.securityEvents.filter(e => e.severity === 'critical').length,
      suspiciousIPs: this.suspiciousIPs.size,
      activeSessions: Array.from(this.activeSessions.values()).filter(expiry => expiry > now).length,
      rateLimitedUsers: Array.from(this.rateLimitMap.values()).filter(r => r.isBlocked).length,
      recentEvents: this.securityEvents.filter(e => e.timestamp > last24Hours)
    };
  }

  // Utility Methods
  private generateEncryptionKey(): string {
    return CryptoJS.lib.WordArray.random(256/8).toString();
  }

  private generateSessionId(): string {
    return CryptoJS.lib.WordArray.random(32).toString();
  }

  private generateEventId(): string {
    return CryptoJS.lib.WordArray.random(16).toString();
  }

  private isSuspiciousPattern(input: string): boolean {
    // Check for common attack patterns
    const suspiciousPatterns = [
      /(.)\1{4,}/, // Repeated characters
      /^[0-9]+$/, // Only numbers
      /^[A-Z]+$/, // Only letters
      /(admin|root|test|demo)/i, // Common test values
    ];
    
    return suspiciousPatterns.some(pattern => pattern.test(input));
  }

  // Configuration Management
  updateSecurityConfig(newConfig: Partial<SecurityConfig>): void {
    this.config = { ...this.config, ...newConfig };
  }

  getSecurityConfig(): SecurityConfig {
    return { ...this.config };
  }

  // Cleanup
  cleanup(): void {
    const now = Date.now();
    
    // Clean expired sessions
    const sessionEntries = Array.from(this.activeSessions.entries());
    for (let i = 0; i < sessionEntries.length; i++) {
      const [sessionId, expiry] = sessionEntries[i];
      if (now > expiry) {
        this.activeSessions.delete(sessionId);
      }
    }
    
    // Clean expired rate limits
    const rateLimitEntries = Array.from(this.rateLimitMap.entries());
    for (let i = 0; i < rateLimitEntries.length; i++) {
      const [identifier, info] = rateLimitEntries[i];
      if (now - info.windowStart > this.config.rateLimitWindow) {
        this.rateLimitMap.delete(identifier);
      }
    }
  }
}

export const securityService = new SecurityService();

// Cleanup every 5 minutes
setInterval(() => {
  securityService.cleanup();
}, 5 * 60 * 1000);
