import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Badge } from './ui/badge';
import { Progress } from './ui/progress';
import { 
  Activity, 
  Shield, 
  Users, 
  Clock, 
  AlertTriangle, 
  CheckCircle, 
  XCircle,
  TrendingUp,
  Database,
  Cpu,
  Wifi
} from 'lucide-react';
import { monitoringService } from '../services/monitoringService';

const MonitoringDashboard: React.FC = () => {
  const [dashboardData, setDashboardData] = useState(monitoringService.getDashboardData());
  const [isExpanded, setIsExpanded] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setDashboardData(monitoringService.getDashboardData());
    }, 5000); // Update every 5 seconds

    return () => clearInterval(interval);
  }, []);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'healthy': return 'text-green-500';
      case 'warning': return 'text-yellow-500';
      case 'critical': return 'text-red-500';
      default: return 'text-gray-500';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'healthy': return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'warning': return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
      case 'critical': return <XCircle className="h-4 w-4 text-red-500" />;
      default: return <Activity className="h-4 w-4 text-gray-500" />;
    }
  };

  const formatUptime = (ms: number) => {
    const hours = Math.floor(ms / (1000 * 60 * 60));
    const minutes = Math.floor((ms % (1000 * 60 * 60)) / (1000 * 60));
    return `${hours}h ${minutes}m`;
  };

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  if (!isExpanded) {
    return (
      <div className="fixed bottom-4 right-4 z-50">
        <Card className="w-80 bg-white/90 backdrop-blur-sm border border-gray-200 shadow-lg">
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm font-medium">System Status</CardTitle>
              <div className="flex items-center gap-2">
                {getStatusIcon(dashboardData.status)}
                <Badge 
                  variant={dashboardData.status === 'healthy' ? 'default' : 'destructive'}
                  className="text-xs"
                >
                  {dashboardData.status.toUpperCase()}
                </Badge>
              </div>
            </div>
          </CardHeader>
          <CardContent className="pt-0">
            <div className="grid grid-cols-2 gap-4 text-xs">
              <div className="flex items-center gap-2">
                <Users className="h-3 w-3 text-blue-500" />
                <span>{dashboardData.metrics.system.activeUsers} users</span>
              </div>
              <div className="flex items-center gap-2">
                <Clock className="h-3 w-3 text-green-500" />
                <span>{formatUptime(dashboardData.metrics.system.uptime)}</span>
              </div>
              <div className="flex items-center gap-2">
                <Activity className="h-3 w-3 text-purple-500" />
                <span>{dashboardData.metrics.voting.totalVotes} votes</span>
              </div>
              <div className="flex items-center gap-2">
                <Shield className="h-3 w-3 text-orange-500" />
                <span>{dashboardData.metrics.security.securityScore}/100</span>
              </div>
            </div>
            {dashboardData.alerts.length > 0 && (
              <div className="mt-2 pt-2 border-t border-gray-200">
                <div className="flex items-center gap-1 text-red-500">
                  <AlertTriangle className="h-3 w-3" />
                  <span className="text-xs">{dashboardData.alerts.length} alerts</span>
                </div>
              </div>
            )}
            <button
              onClick={() => setIsExpanded(true)}
              className="w-full mt-2 text-xs text-blue-600 hover:text-blue-800"
            >
              View Details →
            </button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm">
      <div className="flex items-center justify-center min-h-screen p-4">
        <Card className="w-full max-w-6xl max-h-[90vh] overflow-y-auto bg-white">
          <CardHeader className="pb-4">
            <div className="flex items-center justify-between">
              <CardTitle className="text-xl font-bold">System Monitoring Dashboard</CardTitle>
              <button
                onClick={() => setIsExpanded(false)}
                className="text-gray-500 hover:text-gray-700"
              >
                <XCircle className="h-5 w-5" />
              </button>
            </div>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Status Overview */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    {getStatusIcon(dashboardData.status)}
                    <span className="font-medium">System Status</span>
                  </div>
                  <Badge 
                    variant={dashboardData.status === 'healthy' ? 'default' : 'destructive'}
                    className="mt-2"
                  >
                    {dashboardData.status.toUpperCase()}
                  </Badge>
                </CardContent>
              </Card>
              
              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <Users className="h-4 w-4 text-blue-500" />
                    <span className="font-medium">Active Users</span>
                  </div>
                  <div className="text-2xl font-bold mt-1">
                    {dashboardData.metrics.system.activeUsers}
                  </div>
                </CardContent>
              </Card>
              
              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <Clock className="h-4 w-4 text-green-500" />
                    <span className="font-medium">Uptime</span>
                  </div>
                  <div className="text-sm mt-1">
                    {formatUptime(dashboardData.metrics.system.uptime)}
                  </div>
                </CardContent>
              </Card>
              
              <Card>
                <CardContent className="p-4">
                  <div className="flex items-center gap-2">
                    <Activity className="h-4 w-4 text-purple-500" />
                    <span className="font-medium">Total Votes</span>
                  </div>
                  <div className="text-2xl font-bold mt-1">
                    {dashboardData.metrics.voting.totalVotes}
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Performance Metrics */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <Card>
                <CardHeader>
                  <CardTitle className="text-lg flex items-center gap-2">
                    <TrendingUp className="h-5 w-5" />
                    Performance Metrics
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <div className="flex justify-between text-sm mb-1">
                      <span>Page Load Time</span>
                      <span>{dashboardData.metrics.performance.pageLoadTime.toFixed(0)}ms</span>
                    </div>
                    <Progress 
                      value={Math.min(100, (dashboardData.metrics.performance.pageLoadTime / 3000) * 100)} 
                      className="h-2"
                    />
                  </div>
                  
                  <div>
                    <div className="flex justify-between text-sm mb-1">
                      <span>API Response Time</span>
                      <span>{dashboardData.metrics.performance.apiResponseTime.toFixed(0)}ms</span>
                    </div>
                    <Progress 
                      value={Math.min(100, (dashboardData.metrics.performance.apiResponseTime / 5000) * 100)} 
                      className="h-2"
                    />
                  </div>
                  
                  <div>
                    <div className="flex justify-between text-sm mb-1">
                      <span>Memory Usage</span>
                      <span>{formatBytes(dashboardData.metrics.performance.memoryUsage)}</span>
                    </div>
                    <Progress 
                      value={Math.min(100, (dashboardData.metrics.performance.memoryUsage / (100 * 1024 * 1024)) * 100)} 
                      className="h-2"
                    />
                  </div>
                  
                  <div>
                    <div className="flex justify-between text-sm mb-1">
                      <span>Error Rate</span>
                      <span>{dashboardData.metrics.performance.errorRate.toFixed(1)}%</span>
                    </div>
                    <Progress 
                      value={dashboardData.metrics.performance.errorRate} 
                      className="h-2"
                    />
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle className="text-lg flex items-center gap-2">
                    <Shield className="h-5 w-5" />
                    Security Metrics
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div>
                    <div className="flex justify-between text-sm mb-1">
                      <span>Security Score</span>
                      <span>{dashboardData.metrics.security.securityScore}/100</span>
                    </div>
                    <Progress 
                      value={dashboardData.metrics.security.securityScore} 
                      className="h-2"
                    />
                  </div>
                  
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <div className="text-gray-600">Failed Logins</div>
                      <div className="text-xl font-bold text-red-500">
                        {dashboardData.metrics.security.failedLogins}
                      </div>
                    </div>
                    <div>
                      <div className="text-gray-600">Suspicious Activities</div>
                      <div className="text-xl font-bold text-orange-500">
                        {dashboardData.metrics.security.suspiciousActivities}
                      </div>
                    </div>
                    <div>
                      <div className="text-gray-600">Blocked Requests</div>
                      <div className="text-xl font-bold text-yellow-500">
                        {dashboardData.metrics.security.blockedRequests}
                      </div>
                    </div>
                    <div>
                      <div className="text-gray-600">Rate Limited</div>
                      <div className="text-xl font-bold text-purple-500">
                        {dashboardData.metrics.security.rateLimitedUsers}
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            </div>

            {/* Voting Metrics */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg flex items-center gap-2">
                  <Activity className="h-5 w-5" />
                  Voting Metrics
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="text-center">
                    <div className="text-2xl font-bold text-blue-500">
                      {dashboardData.metrics.voting.totalVotes}
                    </div>
                    <div className="text-sm text-gray-600">Total Votes</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-green-500">
                      {dashboardData.metrics.voting.votesPerMinute.toFixed(1)}
                    </div>
                    <div className="text-sm text-gray-600">Votes/Min</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-purple-500">
                      {dashboardData.metrics.voting.registrationRate}
                    </div>
                    <div className="text-sm text-gray-600">Registrations</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-orange-500">
                      {dashboardData.metrics.voting.completionRate.toFixed(1)}%
                    </div>
                    <div className="text-sm text-gray-600">Completion Rate</div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* System Metrics */}
            <Card>
              <CardHeader>
                <CardTitle className="text-lg flex items-center gap-2">
                  <Database className="h-5 w-5" />
                  System Metrics
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className="text-center">
                    <div className="text-2xl font-bold text-blue-500">
                      {dashboardData.metrics.system.totalSessions}
                    </div>
                    <div className="text-sm text-gray-600">Total Sessions</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-green-500">
                      {dashboardData.metrics.system.databaseConnections}
                    </div>
                    <div className="text-sm text-gray-600">DB Connections</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-purple-500">
                      {dashboardData.metrics.system.cacheHitRate.toFixed(1)}%
                    </div>
                    <div className="text-sm text-gray-600">Cache Hit Rate</div>
                  </div>
                  <div className="text-center">
                    <div className="text-2xl font-bold text-orange-500">
                      {dashboardData.metrics.system.queueSize}
                    </div>
                    <div className="text-sm text-gray-600">Queue Size</div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Alerts */}
            {dashboardData.alerts.length > 0 && (
              <Card>
                <CardHeader>
                  <CardTitle className="text-lg flex items-center gap-2">
                    <AlertTriangle className="h-5 w-5 text-red-500" />
                    Active Alerts ({dashboardData.alerts.length})
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-2 max-h-40 overflow-y-auto">
                    {dashboardData.alerts.map((alert) => (
                      <div
                        key={alert.id}
                        className={`p-3 rounded-lg border-l-4 ${
                          alert.severity === 'critical' ? 'border-red-500 bg-red-50' :
                          alert.severity === 'high' ? 'border-orange-500 bg-orange-50' :
                          alert.severity === 'medium' ? 'border-yellow-500 bg-yellow-50' :
                          'border-blue-500 bg-blue-50'
                        }`}
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <Badge variant={alert.severity === 'critical' ? 'destructive' : 'secondary'}>
                              {alert.severity.toUpperCase()}
                            </Badge>
                            <span className="font-medium">{alert.message}</span>
                          </div>
                          <span className="text-xs text-gray-500">
                            {new Date(alert.timestamp).toLocaleTimeString()}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </CardContent>
              </Card>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default MonitoringDashboard;
