// Comprehensive Monitoring and Analytics Service
export interface MonitoringMetrics {
  performance: PerformanceMetrics;
  security: SecurityMetrics;
  voting: VotingMetrics;
  system: SystemMetrics;
}

export interface PerformanceMetrics {
  pageLoadTime: number;
  apiResponseTime: number;
  memoryUsage: number;
  cpuUsage: number;
  networkLatency: number;
  errorRate: number;
}

export interface SecurityMetrics {
  failedLogins: number;
  suspiciousActivities: number;
  blockedRequests: number;
  rateLimitedUsers: number;
  securityScore: number;
}

export interface VotingMetrics {
  totalVotes: number;
  votesPerMinute: number;
  registrationRate: number;
  completionRate: number;
  averageVotingTime: number;
  errorRate: number;
}

export interface SystemMetrics {
  uptime: number;
  activeUsers: number;
  totalSessions: number;
  databaseConnections: number;
  cacheHitRate: number;
  queueSize: number;
}

export interface Alert {
  id: string;
  type: 'performance' | 'security' | 'voting' | 'system';
  severity: 'low' | 'medium' | 'high' | 'critical';
  message: string;
  timestamp: number;
  resolved: boolean;
  metadata: any;
}

class MonitoringService {
  private metrics: MonitoringMetrics;
  private alerts: Alert[] = [];
  private performanceObserver: PerformanceObserver | null = null;
  private isMonitoring: boolean = false;
  private startTime: number = Date.now();

  constructor() {
    this.metrics = this.initializeMetrics();
    this.startMonitoring();
  }

  private initializeMetrics(): MonitoringMetrics {
    return {
      performance: {
        pageLoadTime: 0,
        apiResponseTime: 0,
        memoryUsage: 0,
        cpuUsage: 0,
        networkLatency: 0,
        errorRate: 0
      },
      security: {
        failedLogins: 0,
        suspiciousActivities: 0,
        blockedRequests: 0,
        rateLimitedUsers: 0,
        securityScore: 100
      },
      voting: {
        totalVotes: 0,
        votesPerMinute: 0,
        registrationRate: 0,
        completionRate: 0,
        averageVotingTime: 0,
        errorRate: 0
      },
      system: {
        uptime: 0,
        activeUsers: 0,
        totalSessions: 0,
        databaseConnections: 0,
        cacheHitRate: 0,
        queueSize: 0
      }
    };
  }

  // Start Monitoring
  startMonitoring(): void {
    if (this.isMonitoring) return;

    this.isMonitoring = true;
    this.startPerformanceMonitoring();
    this.startSecurityMonitoring();
    this.startVotingMonitoring();
    this.startSystemMonitoring();
    
    console.log('Monitoring service started');
  }

  // Performance Monitoring
  private startPerformanceMonitoring(): void {
    // Monitor page load time
    window.addEventListener('load', () => {
      const loadTime = performance.now();
      this.updateMetric('performance', 'pageLoadTime', loadTime);
      this.checkPerformanceThresholds(loadTime);
    });

    // Monitor memory usage
    if ('memory' in performance) {
      setInterval(() => {
        const memory = (performance as any).memory;
        this.updateMetric('performance', 'memoryUsage', memory.usedJSHeapSize);
      }, 5000);
    }

    // Monitor API response times
    this.interceptFetch();
  }

  private interceptFetch(): void {
    const originalFetch = window.fetch;
    window.fetch = async (...args) => {
      const startTime = performance.now();
      try {
        const response = await originalFetch(...args);
        const endTime = performance.now();
        const responseTime = endTime - startTime;
        
        this.updateMetric('performance', 'apiResponseTime', responseTime);
        this.checkApiResponseThresholds(responseTime);
        
        return response;
      } catch (error) {
        this.incrementMetric('performance', 'errorRate');
        this.createAlert('performance', 'high', 'API request failed', { error: error instanceof Error ? error.message : 'Unknown error' });
        throw error;
      }
    };
  }

  // Security Monitoring
  private startSecurityMonitoring(): void {
    // Monitor failed login attempts
    this.onSecurityEvent('failed_login', () => {
      this.incrementMetric('security', 'failedLogins');
      this.updateSecurityScore();
    });

    // Monitor suspicious activities
    this.onSecurityEvent('suspicious_activity', () => {
      this.incrementMetric('security', 'suspiciousActivities');
      this.updateSecurityScore();
    });

    // Monitor blocked requests
    this.onSecurityEvent('blocked_request', () => {
      this.incrementMetric('security', 'blockedRequests');
    });

    // Monitor rate limiting
    this.onSecurityEvent('rate_limited', () => {
      this.incrementMetric('security', 'rateLimitedUsers');
    });
  }

  // Voting Monitoring
  private startVotingMonitoring(): void {
    // Monitor vote casting
    this.onVotingEvent('vote_cast', (data) => {
      this.incrementMetric('voting', 'totalVotes');
      this.updateVotingRate();
    });

    // Monitor voter registration
    this.onVotingEvent('voter_registered', () => {
      this.incrementMetric('voting', 'registrationRate');
    });

    // Monitor voting completion
    this.onVotingEvent('voting_completed', (data) => {
      this.updateMetric('voting', 'completionRate', data.completionRate);
      this.updateMetric('voting', 'averageVotingTime', data.averageTime);
    });

    // Monitor voting errors
    this.onVotingEvent('voting_error', () => {
      this.incrementMetric('voting', 'errorRate');
    });
  }

  // System Monitoring
  private startSystemMonitoring(): void {
    // Update uptime
    setInterval(() => {
      this.updateMetric('system', 'uptime', Date.now() - this.startTime);
    }, 1000);

    // Monitor active users (simplified)
    setInterval(() => {
      const activeUsers = this.getActiveUserCount();
      this.updateMetric('system', 'activeUsers', activeUsers);
    }, 10000);

    // Monitor memory and performance
    setInterval(() => {
      this.updateSystemMetrics();
    }, 5000);
  }

  // Event Handlers
  onSecurityEvent(eventType: string, callback: (data?: any) => void): void {
    // In a real implementation, this would use an event emitter
    // For demo purposes, we'll store the callbacks
    (window as any).securityEventCallbacks = (window as any).securityEventCallbacks || {};
    (window as any).securityEventCallbacks[eventType] = callback;
  }

  onVotingEvent(eventType: string, callback: (data?: any) => void): void {
    (window as any).votingEventCallbacks = (window as any).votingEventCallbacks || {};
    (window as any).votingEventCallbacks[eventType] = callback;
  }

  // Trigger Events (for demo purposes)
  triggerSecurityEvent(eventType: string, data?: any): void {
    const callback = (window as any).securityEventCallbacks?.[eventType];
    if (callback) callback(data);
  }

  triggerVotingEvent(eventType: string, data?: any): void {
    const callback = (window as any).votingEventCallbacks?.[eventType];
    if (callback) callback(data);
  }

  // Metric Updates
  private updateMetric(category: keyof MonitoringMetrics, metric: string, value: number): void {
    (this.metrics[category] as any)[metric] = value;
  }

  private incrementMetric(category: keyof MonitoringMetrics, metric: string): void {
    (this.metrics[category] as any)[metric] = ((this.metrics[category] as any)[metric] || 0) + 1;
  }

  // Threshold Checks
  private checkPerformanceThresholds(loadTime: number): void {
    if (loadTime > 3000) {
      this.createAlert('performance', 'high', 'Page load time exceeded threshold', { loadTime });
    }
  }

  private checkApiResponseThresholds(responseTime: number): void {
    if (responseTime > 5000) {
      this.createAlert('performance', 'medium', 'API response time exceeded threshold', { responseTime });
    }
  }

  private updateSecurityScore(): void {
    const security = this.metrics.security;
    let score = 100;
    
    score -= security.failedLogins * 2;
    score -= security.suspiciousActivities * 5;
    score -= security.blockedRequests * 1;
    score -= security.rateLimitedUsers * 3;
    
    this.updateMetric('security', 'securityScore', Math.max(0, score));
    
    if (score < 70) {
      this.createAlert('security', 'high', 'Security score below threshold', { score });
    }
  }

  private updateVotingRate(): void {
    // Calculate votes per minute (simplified)
    const now = Date.now();
    const oneMinuteAgo = now - 60000;
    
    // In a real implementation, this would track timestamps
    // For demo purposes, we'll use a simple calculation
    this.updateMetric('voting', 'votesPerMinute', this.metrics.voting.totalVotes / 10);
  }

  private updateSystemMetrics(): void {
    // Update system metrics
    this.updateMetric('system', 'totalSessions', this.getTotalSessions());
    this.updateMetric('system', 'databaseConnections', this.getDatabaseConnections());
    this.updateMetric('system', 'cacheHitRate', this.getCacheHitRate());
    this.updateMetric('system', 'queueSize', this.getQueueSize());
  }

  // Alert Management
  createAlert(type: Alert['type'], severity: Alert['severity'], message: string, metadata: any = {}): void {
    const alert: Alert = {
      id: this.generateAlertId(),
      type,
      severity,
      message,
      timestamp: Date.now(),
      resolved: false,
      metadata
    };
    
    this.alerts.push(alert);
    console.warn(`[${severity.toUpperCase()}] ${type}: ${message}`, metadata);
  }

  resolveAlert(alertId: string): void {
    const alert = this.alerts.find(a => a.id === alertId);
    if (alert) {
      alert.resolved = true;
    }
  }

  getActiveAlerts(): Alert[] {
    return this.alerts.filter(alert => !alert.resolved);
  }

  // Data Retrieval
  getMetrics(): MonitoringMetrics {
    return { ...this.metrics };
  }

  getMetricsHistory(): MonitoringMetrics[] {
    // In a real implementation, this would return historical data
    return [this.metrics];
  }

  getDashboardData(): {
    metrics: MonitoringMetrics;
    alerts: Alert[];
    status: 'healthy' | 'warning' | 'critical';
  } {
    const activeAlerts = this.getActiveAlerts();
    const criticalAlerts = activeAlerts.filter(a => a.severity === 'critical');
    const warningAlerts = activeAlerts.filter(a => a.severity === 'high');
    
    let status: 'healthy' | 'warning' | 'critical' = 'healthy';
    if (criticalAlerts.length > 0) status = 'critical';
    else if (warningAlerts.length > 0) status = 'warning';
    
    return {
      metrics: this.metrics,
      alerts: activeAlerts,
      status
    };
  }

  // Utility Methods
  private getActiveUserCount(): number {
    // In a real implementation, this would track actual active users
    return Math.floor(Math.random() * 100) + 50;
  }

  private getTotalSessions(): number {
    return Math.floor(Math.random() * 1000) + 500;
  }

  private getDatabaseConnections(): number {
    return Math.floor(Math.random() * 20) + 10;
  }

  private getCacheHitRate(): number {
    return Math.random() * 20 + 80; // 80-100%
  }

  private getQueueSize(): number {
    return Math.floor(Math.random() * 50);
  }

  private generateAlertId(): string {
    return 'alert_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  }

  // Cleanup
  stopMonitoring(): void {
    this.isMonitoring = false;
    if (this.performanceObserver) {
      this.performanceObserver.disconnect();
    }
    console.log('Monitoring service stopped');
  }
}

export const monitoringService = new MonitoringService();
